"--shiki-light:#267F99;--shiki-dark:#4EC9B0\">threadsPerBlock</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">.</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">x</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">,</span></span>\n<span class=\"line\" data-line=\"21\"><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">                       (</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">M</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\"> + </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">threadsPerBlock</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">.</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">y</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\"> - </span><span style=\"--shiki-light:#098658;--shiki-dark:#B5CEA8\">1</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">) / </span><span style=\"--shiki-light:#267F99;--shiki-dark:#4EC9B0\">threadsPerBlock</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">.</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">y</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">);</span></span>\n<span class=\"line\" data-line=\"22\"></span>\n<span class=\"line\" data-line=\"23\"><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">    matrix_multiplication_kernel</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">&#x3C;&#x3C;&#x3C;</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">blocksPerGrid</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">threadsPerBlock</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">>>>(</span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">A</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">B</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">C</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">M</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">N</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">, </span><span style=\"--shiki-light:#001080;--shiki-dark:#9CDCFE\">K</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">);</span></span>\n<span class=\"line\" data-line=\"24\"><span style=\"--shiki-light:#795E26;--shiki-dark:#DCDCAA\">    cudaDeviceSynchronize</span><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">();</span></span>\n<span class=\"line\" data-line=\"25\"><span style=\"--shiki-light:#000000;--shiki-dark:#D4D4D4\">}</span></span></code></pre></div>\n</div><hr>\n"
